import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"3. 聊天与社交","description":"","frontmatter":{},"headers":[],"relativePath":"chat.md","filePath":"chat.md"}'),r={name:"chat.md"};function l(c,t,n,h,i,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_3-聊天与社交" tabindex="-1">3. 聊天与社交 <a class="header-anchor" href="#_3-聊天与社交" aria-label="Permalink to &quot;3. 聊天与社交&quot;">​</a></h1><h2 id="_3-1-聊天频道" tabindex="-1">3.1 聊天频道 <a class="header-anchor" href="#_3-1-聊天频道" aria-label="Permalink to &quot;3.1 聊天频道&quot;">​</a></h2><p>服务器默认频道是 <strong>Global（全球）</strong>，直接打字即可在全服发言。</p><table tabindex="0"><thead><tr><th>频道</th><th>进入方式</th><th>用途</th></tr></thead><tbody><tr><td>Global</td><td>默认；<code>/channel Global</code></td><td>全服聊天</td></tr><tr><td>Union</td><td><code>/channel Union</code>；或 <code>/union chat &lt;消息&gt;</code></td><td>联盟内部聊天</td></tr><tr><td>私聊</td><td><code>/msg &lt;玩家&gt; &lt;消息&gt;</code></td><td>一对一私聊</td></tr></tbody></table><p><code>/channel</code> 可以查看、加入、离开和切换频道。聊天栏会显示你的称号、联盟标签和名字。</p><h2 id="_3-2-私聊与屏蔽" tabindex="-1">3.2 私聊与屏蔽 <a class="header-anchor" href="#_3-2-私聊与屏蔽" aria-label="Permalink to &quot;3.2 私聊与屏蔽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/msg &lt;玩家&gt; &lt;消息&gt;</code></td><td>私聊；别名 <code>/w</code>、<code>/tell</code>、<code>/m</code>、<code>/whisper</code></td></tr><tr><td><code>/reply &lt;消息&gt;</code></td><td>回复最近给你发私聊的人；别名 <code>/r</code></td></tr><tr><td><code>/ignore &lt;玩家&gt;</code></td><td>屏蔽某人的聊天与私聊</td></tr><tr><td><code>/ignore</code></td><td>查看/管理屏蔽列表</td></tr></tbody></table><h2 id="_3-3-聊天限制" tabindex="-1">3.3 聊天限制 <a class="header-anchor" href="#_3-3-聊天限制" aria-label="Permalink to &quot;3.3 聊天限制&quot;">​</a></h2><ul><li>发言冷却 <strong>2 秒</strong>。</li><li>单条消息最多 <strong>100 个字符</strong>。</li><li>有相似度防刷屏检测，连续重复内容可能被拦截。</li><li>彩色文字需要对应权限；普通玩家请使用纯文本，带 <code>&amp;</code> 的彩色内容可能被过滤。</li><li>联盟频道只对同联盟成员可见。</li></ul>',9)])])}const g=e(r,[["render",l]]);export{b as __pageData,g as default};
